INSERT INTO quests (id,name,quest_lvl,loc,giver,chain,hint,steps_json,reward_json,is_instance) VALUES
('q_g001','Ночное Кузнечное Дело · 1: Вторая страница',1,'ashfields','gilda','Ночное Кузнечное Дело','Без лунный камень горн остынет, а лавка опустеет. Нужно 4.','[{"text": "Собери: лунный камень (4).", "type": "collect", "item": "moonstone", "count": 4}, {"text": "Перебей помех: тенивый волк (2).", "type": "kill", "mob": "wolf", "count": 2}, {"text": "Принеси добычу: Гильда Торговый Путь.", "type": "talk", "npc": "gilda"}]','{"xp": 44, "gold": 14, "items": [], "rep": {"umbral": 2}}',0),
('q_g002','Сумеречный Обряд · 1: Третья страница',1,'grove','dormir','Сумеречный Обряд','Эхо этого места помнит сотни героев. Ни один не вернулся с пустыми руками.','[{"text": "Получи заказ у: Дормир Молот (Роща Шепчущих Кострей).", "type": "talk", "npc": "dormir"}, {"text": "Уничтожь в инстансе: неупокоенный воин (4).", "type": "kill", "mob": "skeleton", "count": 4}, {"text": "Вернись с доказательством: Дормир Молот.", "type": "talk", "npc": "dormir"}]','{"xp": 44, "gold": 14, "items": [], "rep": {"dusk": 2}}',1),
('q_g003','Тёмный Долг · 1: Четвёртая страница',1,'aeriadocks','bruno','Тёмный Долг','Тёмный Долг. Два вида тварей — два повода вернуться засветло.','[{"text": "Уничтожь: неупокоенный воин (2).", "type": "kill", "mob": "skeleton", "count": 2}, {"text": "Уничтожь: тенивый волк (5).", "type": "kill", "mob": "wolf", "count": 5}, {"text": "Отчитайся: Бруно Железнобокий (Причалы Аэрии).", "type": "talk", "npc": "bruno"}]','{"xp": 44, "gold": 14, "items": [], "rep": {"order": 1}}',0),
('q_g004','Пепельное Покаяние · 1: Пятая страница',1,'minecamp','ilva','Пепельное Покаяние','Поговори. Иногда задание — это просто чужое внимание в ночи.','[{"text": "Поговори с: Ведьма Илва (Разрытая Шахта).", "type": "talk", "npc": "ilva"}, {"text": "Добудь: железную руду (6).", "type": "collect", "item": "iron_ore", "count": 6}, {"text": "Принеси результат: Ведьма Илва.", "type": "talk", "npc": "ilva"}]','{"xp": 44, "gold": 14, "items": [], "rep": {"forge": 3}}',0),
('q_g005','Кости Первых Дозоров · 2: Шестая страница',2,'minecamp','maera','Кости Первых Дозоров','Пока тенивый волк дышит, факелы гаснут один за другим. Кончи это.','[{"text": "Уничтожь: тенивый волк (4).", "type": "kill", "mob": "wolf", "count": 4}, {"text": "Доложи: Мэйра Тихий Яд (Разрытая Шахта).", "type": "talk", "npc": "maera"}]','{"xp": 59, "gold": 19, "items": ["bone_fragment"], "rep": {"umbral": 2}}',0),
('q_g006','Жила Глубже Сердца · 2: Седьмая страница',2,'pinewood','gilda','Жила Глубже Сердца','Ремесло кормится тем, что даёт ночь. Принеси 5: пузырьки яда.','[{"text": "Собери: пузырьки яда (5).", "type": "collect", "item": "poison_vial", "count": 5}, {"text": "Перебей помех: неупокоенный воин (2).", "type": "kill", "mob": "skeleton", "count": 2}, {"text": "Принеси добычу: Гильда Торговый Путь.", "type": "talk", "npc": "gilda"}]','{"xp": 59, "gold": 19, "items": [], "rep": {"dusk": 2}}',0),
('q_g007','Дозор Ночи · 2: Первая страница',2,'barrow','serj','Дозор Ночи','Внутри — тьма плотнее обычной. Возьми группу или скажи себе «прощай».','[{"text": "Получи заказ у: Сержант Вьюг (Курганы Первых Дозоров).", "type": "talk", "npc": "serj"}, {"text": "Уничтожь в инстансе: неупокоенный воин (4).", "type": "kill", "mob": "skeleton", "count": 4}, {"text": "Вернись с доказательством: Сержант Вьюг.", "type": "talk", "npc": "serj"}]','{"xp": 59, "gold": 19, "items": ["mana_potion"], "rep": {"order": 1}}',1),
('q_g008','Ночное Кузнечное Дело · 2: Вторая страница',2,'hollow','bruno','Ночное Кузнечное Дело','Ночное Кузнечное Дело. Два вида тварей — два повода вернуться засветло.','[{"text": "Уничтожь: тенивый волк (2).", "type": "kill", "mob": "wolf", "count": 2}, {"text": "Уничтожь: тенивый волк (2).", "type": "kill", "mob": "wolf", "count": 2}, {"text": "Отчитайся: Бруно Железнобокий (Выгоршая Пустошь).", "type": "talk", "npc": "bruno"}]','{"xp": 59, "gold": 19, "items": [], "rep": {"forge": 3}}',0),
('q_g009','Сумеречный Обряд · 3: Третья страница',3,'outpost','dormir','Сумеречный Обряд','Свет держится на словах, сказанных вовремя. Найди того, кто слушает.','[{"text": "Поговори с: Дормир Молот (Ночная Застава).", "type": "talk", "npc": "dormir"}, {"text": "Добудь: костяные обломки (6).", "type": "collect", "item": "bone_fragment", "count": 6}, {"text": "Принеси результат: Дормир Молот.", "type": "talk", "npc": "dormir"}]','{"xp": 75, "gold": 23, "items": ["health_potion"], "rep": {"umbral": 2}}',0),
('q_g010','Тёмный Долг · 3: Четвёртая страница',3,'outpost','maera','Тёмный Долг','Застава считает не дни, а убитые тени. Внеси свои 3 в счёт.','[{"text": "Уничтожь: неупокоенный воин (3).", "type": "kill", "mob": "skeleton", "count": 3}, {"text": "Доложи: Мэйра Тихий Яд (Ночная Застава).", "type": "talk", "npc": "maera"}]','{"xp": 75, "gold": 23, "items": ["wraith_essence"], "rep": {"dusk": 2}}',0),
('q_g011','Пепельное Покаяние · 3: Пятая страница',3,'ashfields','ilva','Пепельное Покаяние','Это не жадность — это снабжение заставы. 6, и ни одним меньше.','[{"text": "Собери: шкуры химер (6).", "type": "collect", "item": "chimera_hide", "count": 6}, {"text": "Перебей помех: неупокоенный воин (2).", "type": "kill", "mob": "skeleton", "count": 2}, {"text": "Принеси добычу: Ведьма Илва.", "type": "talk", "npc": "ilva"}]','{"xp": 75, "gold": 23, "items": [], "rep": {"order": 1}}',0),
('q_g012','Кости Первых Дозоров · 3: Шестая страница',3,'grove','serj','Кости Первых Дозоров','Врата входа открыты только тем, кто готов умереть красиво и быстро.','[{"text": "Получи заказ у: Сержант Вьюг (Роща Шепчущих Кострей).", "type": "talk", "npc": "serj"}, {"text": "Уничтожь в инстансе: тенивый волк (4).", "type": "kill", "mob": "wolf", "count": 4}, {"text": "Вернись с доказательством: Сержант Вьюг.", "type": "talk", "npc": "serj"}]','{"xp": 75, "gold": 23, "items": [], "rep": {"forge": 3}}',1),
('q_g013','Жила Глубже Сердца · 4: Седьмая страница',4,'aeriadocks','gilda','Жила Глубже Сердца','Жила Глубже Сердца. Два вида тварей — два повода вернуться засветло.','[{"text": "Уничтожь: тенивый волк (2).", "type": "kill", "mob": "wolf", "count": 2}, {"text": "Уничтожь: тенивый волк (3).", "type": "kill", "mob": "wolf", "count": 3}, {"text": "Отчитайся: Гильда Торговый Путь (Причалы Аэрии).", "type": "talk", "npc": "gilda"}]','{"xp": 91, "gold": 28, "items": [], "rep": {"umbral": 2}}',0),
('q_g014','Дозор Ночи · 4: Первая страница',4,'minecamp','dormir','Дозор Ночи','Пусть знает, что ночь короче, чем кажется.','[{"text": "Поговори с: Дормир Молот (Разрытая Шахта).", "type": "talk", "npc": "dormir"}, {"text": "Добудь: эссенции упыря (6).", "type": "collect", "item": "wraith_essence", "count": 6}, {"text": "Принеси результат: Дормир Молот.", "type": "talk", "npc": "dormir"}]','{"xp": 91, "gold": 28, "items": ["mana_potion"], "rep": {"dusk": 2}}',0),
('q_g015','Ночное Кузнечное Дело · 4: Вторая страница',4,'minecamp','bruno','Ночное Кузнечное Дело','Тьма не торгуется. Она просто ждёт, пока ты посчитаешь до 3.','[{"text": "Уничтожь: неупокоенный воин (3).", "type": "kill", "mob": "skeleton", "count": 3}, {"text": "Доложи: Бруно Железнобокий (Разрытая Шахта).", "type": "talk", "npc": "bruno"}]','{"xp": 91, "gold": 28, "items": ["moonstone"], "rep": {"order": 1}}',0),
('q_g016','Сумеречный Обряд · 4: Третья страница',4,'pinewood','ilva','Сумеречный Обряд','Без осколки люминита горн остынет, а лавка опустеет. Нужно 3.','[{"text": "Собери: осколки люминита (3).", "type": "collect", "item": "lum_shard", "count": 3}, {"text": "Перебей помех: тенивый волк (2).", "type": "kill", "mob": "wolf", "count": 2}, {"text": "Принеси добычу: Ведьма Илва.", "type": "talk", "npc": "ilva"}]','{"xp": 91, "gold": 28, "items": [], "rep": {"forge": 3}}',0),
('q_g017','Тёмный Долг · 5: Четвёртая страница',5,'barrow','maera','Тёмный Долг','Эхо этого места помнит сотни героев. Ни один не вернулся с пустыми руками.','[{"text": "Получи заказ у: Мэйра Тихий Яд (Курганы Первых Дозоров).", "type": "talk", "npc": "maera"}, {"text": "Уничтожь в инстансе: тенивый волк (4).", "type": "kill", "mob": "wolf", "count": 4}, {"text": "Вернись с доказательством: Мэйра Тихий Яд.", "type": "talk", "npc": "maera"}]','{"xp": 108, "gold": 32, "items": [], "rep": {"umbral": 2}}',1),
